var data = $input.first().json;
var session = null;
if (Array.isArray(data) && data.length > 0) {
  session = data[0];
} else if (data && typeof data === 'object' && data.id) {
  session = data;
}

if (!session) {
  return [{
    json: {
      error: 'no_route_selected',
      message: 'No route is currently selected.',
      spoken: 'I need to know which route you want to work on first.'
    }
  }];
}

return [{
  json: {
    session_id: session.id,
    machine_id: session.current_machine_id,
    item_index: session.current_item_index || 1,
    pick_direction: session.pick_direction || 'forward'
  }
}];

var extractData = $('Extract Session').first().json;
if (extractData.error) {
  return [{ json: extractData }];
}

var sessionData = extractData;
var itemsData = $input.all();

var items = [];
for (var i = 0; i < itemsData.length; i++) {
  var item = itemsData[i].json;
  if (item && item.id) {
    items.push(item);
  }
}

if (items.length === 0) {
  return [{
    json: {
      error: 'No items found',
      session_id: sessionData.session_id
    }
  }];
}

var currentIndex = sessionData.item_index;
var nextIndex;
var nextItem;

if (sessionData.pick_direction === 'reverse') {
  nextIndex = currentIndex - 1;
  if (nextIndex < 1) {
    return [{
      json: {
        action: 'next_machine',
        session_id: sessionData.session_id,
        machine_id: sessionData.machine_id,
        machine_name: items[0].machine_name
      }
    }];
  }
  nextItem = items[items.length - nextIndex];
} else {
  nextIndex = currentIndex + 1;
  if (nextIndex > items.length) {
    return [{
      json: {
        action: 'next_machine',
        session_id: sessionData.session_id,
        machine_id: sessionData.machine_id,
        machine_name: items[0].machine_name
      }
    }];
  }
  nextItem = items[nextIndex - 1];
}

return [{
  json: {
    action: 'next_item',
    session_id: sessionData.session_id,
    next_item_index: nextIndex,
    product_name: nextItem.product_name,
    quantity: nextItem.quantity,
    slot: nextItem.slot,
    inventory_current: nextItem.inventory_current || 0,
    inventory_parlevel: nextItem.inventory_parlevel || 0,
    items_remaining: items.length - nextIndex,
    machine_name: nextItem.machine_name
  }
}];

var determineData = $('Determine Next State').first().json;
if (determineData.error) {
  return [{ json: determineData }];
}

var data = determineData;

function formatSlotForTTS(slot) {
  if (!slot) return null;
  slot = String(slot);

  if (slot.indexOf('-') !== -1) {
    var parts = slot.split('-');
    var first = parseInt(parts[0], 10);
    var second = parseInt(parts[1], 10);
    if (!isNaN(first) && !isNaN(second)) {
      return 'slots ' + first + ' and ' + second;
    }
    return slot;
  }

  var num = parseInt(slot, 10);
  if (!isNaN(num)) {
    return 'slot ' + num;
  }

  return slot;
}

function fixPronunciation(text) {
  if (!text) return text;
  text = text.replace(/\bCan\b/g, 'Kan');
  text = text.replace(/\bCAN\b/g, 'KAN');
  text = text.replace(/\boz\b/gi, 'ounce');
  text = text.replace(/\bct\b/gi, 'count');
  text = text.replace(/\bpk\b/gi, 'pack');
  return text;
}

function parseProductName(productName) {
  if (!productName) return { baseName: '', size: '', type: '' };

  var name = productName;
  var size = '';
  var type = '';

  var sizePatterns = [
    { regex: /(\d+\.?\d*)\s*(oz|ounce|ounces)/gi, unit: 'ounce' },
    { regex: /(\d+\.?\d*)\s*(ml|milliliter|milliliters)/gi, unit: 'milliliter' },
    { regex: /(\d+\.?\d*)\s*(l|liter|liters)/gi, unit: 'liter' },
    { regex: /(\d+\.?\d*)\s*(g|gram|grams)/gi, unit: 'gram' }
  ];

  for (var i = 0; i < sizePatterns.length; i++) {
    var pattern = sizePatterns[i];
    var match = pattern.regex.exec(name);
    if (match) {
      var value = match[1];
      var unit = pattern.unit;
      var numValue = parseFloat(value);
      if (numValue !== 1.0) {
        unit = unit + 's';
      }
      size = value + ' ' + unit;
      name = name.replace(match[0], '').trim();
      break;
    }
  }

  var typePatterns = [
    { regex: /\b(bar|bars)\b/gi, normalized: 'bars' },
    { regex: /\b(can|cans|kan|kans)\b/gi, normalized: 'cans' },
    { regex: /\b(bottle|bottles)\b/gi, normalized: 'bottles' },
    { regex: /\b(bag|bags)\b/gi, normalized: 'bags' },
    { regex: /\b(pack|packs)\b/gi, normalized: 'packs' },
    { regex: /\b(box|boxes)\b/gi, normalized: 'boxes' }
  ];

  for (var j = 0; j < typePatterns.length; j++) {
    var typePattern = typePatterns[j];
    var typeMatch = typePattern.regex.exec(name);
    if (typeMatch) {
      type = typePattern.normalized;
      name = name.replace(typeMatch[0], '').trim();
      break;
    }
  }

  if (!type) {
    var lowerName = name.toLowerCase();
    if (lowerName.indexOf('snickers') !== -1 || lowerName.indexOf('twix') !== -1 || lowerName.indexOf('kitkat') !== -1 || lowerName.indexOf('hershey') !== -1 || lowerName.indexOf('reese') !== -1) {
      type = 'bars';
    }
    if (lowerName.indexOf('coke') !== -1 || lowerName.indexOf('pepsi') !== -1 || lowerName.indexOf('sprite') !== -1 || lowerName.indexOf('dr pepper') !== -1 || lowerName.indexOf('monster') !== -1 || lowerName.indexOf('red bull') !== -1) {
      type = 'cans';
    }
    if (lowerName.indexOf('water') !== -1 || lowerName.indexOf('gatorade') !== -1 || lowerName.indexOf('powerade') !== -1) {
      type = 'bottles';
    }
    if (lowerName.indexOf('doritos') !== -1 || lowerName.indexOf('cheetos') !== -1 || lowerName.indexOf('lays') !== -1 || lowerName.indexOf('fritos') !== -1) {
      type = 'bags';
    }
  }

  return { baseName: name, size: size, type: type };
}

var slotSpoken = formatSlotForTTS(data.slot);
var spoken;

if (data.action === 'next_item') {
  var parsed = parseProductName(data.product_name);
  var productName = fixPronunciation(parsed.baseName);
  var parts = [data.quantity, productName];
  if (parsed.size) parts.push(parsed.size);
  if (parsed.type) parts.push(parsed.type);
  spoken = parts.join(' ');
} else if (data.action === 'next_machine') {
  spoken = 'All items complete for this machine. Say top or bottom for the next machine, or skip machine to move on.';
}

return [{
  json: {
    action: data.action,
    product_name: data.product_name,
    quantity: data.quantity,
    slot: data.slot,
    slot_spoken: slotSpoken,
    inventory_current: data.inventory_current || 0,
    inventory_parlevel: data.inventory_parlevel || 0,
    items_remaining: data.items_remaining || 0,
    machine_name: data.machine_name,
    next_machine_id: data.next_machine_id || null,
    spoken: spoken
  }
}];
